/* @autogenerated */
package net.civeira.phylax.feature.oauth.webauthn.infrastructure.driven;

import java.time.OffsetDateTime;
import java.time.ZoneOffset;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.oauth.webauthn.domain.WebAuthnChallenge;

/** The short lived WebAuthn challenges kept on memory. */
class WebAuthnChallengeAdapterUnitTest {
  private final WebAuthnChallengeAdapter adapter = new WebAuthnChallengeAdapter();

  private WebAuthnChallenge challenge(String id, int minutes) {
    OffsetDateTime now = OffsetDateTime.now(ZoneOffset.UTC);
    return WebAuthnChallenge.builder().challengeId(id).tenantId("acme").challenge("abc")
        .type("authentication").createdAt(now).expiresAt(now.plusMinutes(minutes)).build();
  }

  @Test
  @DisplayName("A stored challenge is found only on its tenant")
  void found_on_its_tenant() {
    adapter.store(challenge("c1", 5));

    Assertions.assertEquals("abc", adapter.findById("c1", "acme").orElseThrow().getChallenge());
    Assertions.assertTrue(adapter.findById("c1", "other").isEmpty());
    Assertions.assertTrue(adapter.findById("missing", "acme").isEmpty());
    Assertions.assertTrue(adapter.findById(null, "acme").isEmpty());
    Assertions.assertTrue(adapter.findById("c1", null).isEmpty());
  }

  @Test
  @DisplayName("A verified challenge replaces the pending one")
  void mark_verified() {
    WebAuthnChallenge pending = challenge("c1", 5);
    adapter.store(pending);

    adapter.markVerified(pending.markVerified("user-1", "alice"));

    WebAuthnChallenge found = adapter.findById("c1", "acme").orElseThrow();
    Assertions.assertTrue(found.isVerified());
    Assertions.assertEquals("alice", found.getVerifiedUsername().orElseThrow());
  }

  @Test
  @DisplayName("The purge removes only the expired challenges")
  void purge_expired() {
    adapter.store(challenge("live", 5));
    adapter.store(challenge("expired", -1));

    adapter.purgeExpired();

    Assertions.assertTrue(adapter.findById("live", "acme").isPresent());
    Assertions.assertTrue(adapter.findById("expired", "acme").isEmpty());
  }
}
